"""API views."""
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAdminUser
from rest_framework import viewsets

from .serializers import (
    QueryRequestSerializer, QueryResponseSerializer,
    AIQuerySampleSerializer, AIPromptTemplateSerializer,
)
from ..orchestrator import QueryOrchestrator
from ..models import AIQuerySample, AIPromptTemplate


class AnalyzeView(APIView):
    """POST /api/ai-assistant/analyze/ — Фаза 1: decompose + валидация."""
    permission_classes = []

    def post(self, request):
        text = request.data.get("text", "")
        if not text:
            return Response({"error": "text required"}, status=400)
        result = QueryOrchestrator().analyze(text=text)
        return Response(result)


class ExecuteView(APIView):
    """POST /api/ai-assistant/execute/ — Фаза 2: выполнение графа задач."""
    permission_classes = []

    def post(self, request):
        tasks = request.data.get("tasks", [])
        global_reqs = request.data.get("global_requirements", {})
        if not tasks:
            return Response({"error": "tasks required"}, status=400)
        result = QueryOrchestrator().execute(tasks=tasks, global_reqs=global_reqs)
        return Response(result)


class QueryView(APIView):
    """POST /api/ai-assistant/query/ — старый однофазный (совместимость)."""
    permission_classes = []

    def post(self, request):
        text = request.data.get("text", "")
        if not text:
            return Response({"error": "text required"}, status=400)
        result = QueryOrchestrator().analyze(text=text)
        return Response(result)


class RunQueryView(APIView):
    """POST /api/ai-assistant/run-query/ — отладка."""
    permission_classes = [IsAdminUser]

    def post(self, request):
        text = request.data.get("text", "")
        if not text:
            return Response({"error": "text required"}, status=400)
        result = QueryOrchestrator().analyze(text=text)
        return Response(result)


class QuerySampleViewSet(viewsets.ModelViewSet):
    queryset = AIQuerySample.objects.all()
    serializer_class = AIQuerySampleSerializer
    permission_classes = [IsAdminUser]


class PromptViewSet(viewsets.ModelViewSet):
    queryset = AIPromptTemplate.objects.all()
    serializer_class = AIPromptTemplateSerializer
    permission_classes = [IsAdminUser]

from rest_framework import serializers

from ..models import (
    AIConversation, AIMessage, AITokenUsage,
    AIClientProvider, AIQuerySample, AIPromptTemplate,
)


class AIConversationSerializer(serializers.ModelSerializer):
    class Meta:
        model = AIConversation
        fields = "__all__"


class AIMessageSerializer(serializers.ModelSerializer):
    class Meta:
        model = AIMessage
        fields = "__all__"


class AITokenUsageSerializer(serializers.ModelSerializer):
    class Meta:
        model = AITokenUsage
        fields = "__all__"


class AIQuerySampleSerializer(serializers.ModelSerializer):
    class Meta:
        model = AIQuerySample
        fields = "__all__"


class AIPromptTemplateSerializer(serializers.ModelSerializer):
    class Meta:
        model = AIPromptTemplate
        fields = "__all__"


class QueryRequestSerializer(serializers.Serializer):
    text = serializers.CharField(required=True, max_length=4096)
    session_key = serializers.CharField(required=False, max_length=64)
    customer_id = serializers.IntegerField(required=False)


class QueryResponseSerializer(serializers.Serializer):
    conversation_id = serializers.IntegerField()
    intent = serializers.CharField()
    confidence = serializers.FloatField(required=False)
    filters = serializers.JSONField(required=False, allow_null=True)
    search_results = serializers.JSONField(required=False)
    total_tokens = serializers.IntegerField(required=False)
    total_cost = serializers.FloatField(required=False)
    latency_ms = serializers.IntegerField(required=False)
    reply_text = serializers.CharField()

from django.contrib import admin
from .models import (
    AIConversation, AIMessage, AITokenUsage,
    AIClientProvider, AIQuerySample, AIPromptTemplate,
)


@admin.register(AIConversation)
class AIConversationAdmin(admin.ModelAdmin):
    list_display = ("id", "customer", "status", "intent", "source", "created_at")
    list_filter = ("status", "source", "intent")
    search_fields = ("session_key",)
    readonly_fields = ("created_at", "updated_at")


@admin.register(AIMessage)
class AIMessageAdmin(admin.ModelAdmin):
    list_display = ("id", "conversation", "role", "intent", "confidence", "is_error", "created_at")
    list_filter = ("role", "intent", "is_error")
    search_fields = ("content", "error_message")
    readonly_fields = ("created_at",)


@admin.register(AITokenUsage)
class AITokenUsageAdmin(admin.ModelAdmin):
    list_display = ("id", "message", "model", "prompt_tokens", "completion_tokens", "total_tokens")


@admin.register(AIClientProvider)
class AIClientProviderAdmin(admin.ModelAdmin):
    list_display = ("id", "customer", "provider_type", "is_active")


@admin.register(AIQuerySample)
class AIQuerySampleAdmin(admin.ModelAdmin):
    list_display = ("id", "category", "expected_intent", "is_valid", "created_at")
    list_filter = ("category", "is_valid", "expected_intent")
    search_fields = ("text",)
    list_editable = ("is_valid", "category", "expected_intent")


@admin.register(AIPromptTemplate)
class AIPromptTemplateAdmin(admin.ModelAdmin):
    list_display = ("name", "version", "intent", "is_active")
    list_filter = ("is_active", "intent")
    search_fields = ("name", "template_text")
    list_editable = ("is_active",)

